// Compact deterministic representation: base rows are generated by ID, never
// allocated as 10M JS objects. Only immutable block descriptors and writes live
// here. This models publication/replay, not the engine's wire formats or timings.
export const MiB = 1024 * 1024;
export const BLOCK_BYTES = 120 * 1024;
export const ROWS_PER_BLOCK = 170;
export const PACK_BLOCKS = 8; // 960 KiB: below 1 MiB and the engine's 12-block cap.
export const SEAL_LOGS = 32;
export const BUDGET = Object.freeze({candidates: 12, requests: 8, bytes: MiB});
export const SEED = 0x61de2026;
// Shared by the view and tests; neither queries nor writes can move a preset.
export const QUERY_PRESETS = Object.freeze([
  Object.freeze({x: .24, y: .24}), Object.freeze({x: .5, y: .5}), Object.freeze({x: .76, y: .76}),
]);
export const QUERY_ANIMATION_MS = 1200;
// Keep tiny CPU phases legible in the trace. Unclamped phases retain their
// relative timing; animation and layout use these same shares.
export function queryPhaseFractions(plan) {
  const minimum = .14, fractions = plan.phases.map(() => 0);
  let pending = plan.phases.map((phase, i) => ({ms: phase.ms, i})), remaining = 1;
  while (pending.length) {
    const total = pending.reduce((sum, phase) => sum + phase.ms, 0);
    const small = pending.filter(phase => phase.ms / total * remaining < minimum);
    if (!small.length) {
      for (const phase of pending) fractions[phase.i] = phase.ms / total * remaining;
      break;
    }
    for (const phase of small) { fractions[phase.i] = minimum; remaining -= minimum; }
    pending = pending.filter(phase => !small.includes(phase));
  }
  return fractions;
}
// Absolute elapsed time: skipped frames never lengthen the illustration.
export function queryAnimationProgress(elapsed, plan) {
  const fractions = queryPhaseFractions(plan), position = Math.max(0, elapsed) / QUERY_ANIMATION_MS;
  let start = 0;
  const phases = fractions.map(fraction => {
    const progress = Math.max(0, Math.min(1, (position - start) / fraction));
    start += fraction;
    return progress;
  });
  const active = phases.findIndex(p => p < 1), stage = active < 0 ? 3 : active;
  const remoteCount = plan.sources.s3;
  const batches = Math.ceil(remoteCount / 4);
  const completed = Math.min(batches, Math.floor(phases[2] * batches));
  return {stage, phases, remoteDone: Math.min(remoteCount, completed * 4), done: elapsed >= QUERY_ANIMATION_MS};
}

export function prng(seed) {
  let value = seed >>> 0;
  return () => {
    value = (value + 0x6D2B79F5) >>> 0;
    let t = Math.imul(value ^ value >>> 15, 1 | value);
    t ^= t + Math.imul(t ^ t >>> 7, 61 | t);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const distance = (a, b) => (a.x - b.x) ** 2 + (a.y - b.y) ** 2;
function gaussian(random) {
  return Math.sqrt(-2 * Math.log(Math.max(random(), Number.EPSILON))) * Math.cos(2 * Math.PI * random());
}
export function generateDataset(count, seed = SEED) {
  if (!Number.isInteger(count) || count < 1000 || count > 10_000_000) throw new Error('Dataset size must be 1K–10M');
  const random = prng(seed), n = Math.ceil(count / 4000);
  // Seeded Gaussian-mixture islands with Poisson-disc spacing, rather than a
  // lattice. A spatial hash keeps generation bounded at 2,500 centres.
  const islands = Array.from({length: 9}, () => ({x: .1 + .8 * random(), y: .1 + .8 * random(), spread: .07 + .14 * random()}));
  const spacing = .48 / Math.sqrt(n), cells = new Map(), centroids = [];
  while (centroids.length < n) {
    const island = islands[Math.floor(random() * islands.length)], uniform = random() < .3;
    const x = uniform ? .04 + .92 * random() : island.x + gaussian(random) * island.spread;
    const y = uniform ? .04 + .92 * random() : island.y + gaussian(random) * island.spread;
    if (x < .04 || x > .96 || y < .04 || y > .96) continue;
    const gx = Math.floor(x / spacing), gy = Math.floor(y / spacing);
    let crowded = false;
    for (let dx = -1; dx <= 1; dx++) for (let dy = -1; dy <= 1; dy++) {
      for (const c of cells.get(`${gx + dx},${gy + dy}`) ?? []) if (distance(c, {x, y}) < spacing ** 2) crowded = true;
    }
    if (crowded) continue;
    const c = {id: centroids.length, x, y, radius: (.22 + .27 * random()) / Math.sqrt(n),
      aspect: .4 + .5 * random(), angle: random() * Math.PI, weight: .35 + 2.4 * random() ** 2};
    centroids.push(c);
    const key = `${gx},${gy}`;
    if (!cells.has(key)) cells.set(key, []);
    cells.get(key).push(c);
  }
  const weight = centroids.reduce((sum, c) => sum + c.weight, 0);
  let firstId = 1, cumulative = 0;
  for (const c of centroids) {
    cumulative += c.weight;
    const end = c.id === n - 1 ? count + 1 : 1 + Math.round(count * cumulative / weight);
    c.firstId = firstId; c.count = end - firstId; firstId = end;
    delete c.weight;
  }
  return {count, seed, centroids};
}
export function assignCluster(dataset, point) {
  let best = dataset.centroids[0];
  for (const c of dataset.centroids) if (distance(c, point) < distance(best, point)) best = c;
  return best.id;
}
export function basePoint(dataset, id) {
  if (!Number.isInteger(id) || id < 1 || id > dataset.count) return null;
  let lo = 0, hi = dataset.centroids.length;
  while (lo + 1 < hi) {
    const mid = (lo + hi) >>> 1;
    if (dataset.centroids[mid].firstId <= id) lo = mid; else hi = mid;
  }
  const c = dataset.centroids[lo];
  const random = prng((dataset.seed ^ Math.imul(id, 0x9E3779B1)) >>> 0);
  const u = gaussian(random) * c.radius, v = gaussian(random) * c.radius * c.aspect;
  // Cluster membership represents the original embedding; its 2D projection
  // may overlap other islands. Smoothly bound tails without piling up at edges.
  const project = (centre, offset) => {
    const span = offset < 0 ? centre - .01 : .99 - centre;
    return centre + span * Math.tanh(offset / span);
  };
  return {id, cluster: c.id, x: project(c.x, u * Math.cos(c.angle) - v * Math.sin(c.angle)),
    y: project(c.y, u * Math.sin(c.angle) + v * Math.cos(c.angle))};
}
export function sampleDataset(dataset, limit = 30000) {
  const count = Math.min(limit, dataset.count);
  return Array.from({length: count}, (_, i) => basePoint(dataset, 1 + Math.floor(i * dataset.count / count)));
}

export class LRU {
  constructor(capacity) { this.capacity = capacity; this.entries = new Map(); this.bytes = 0; this.evictions = 0; }
  has(key) { return this.entries.has(key); }
  touch(key) {
    const bytes = this.entries.get(key);
    if (bytes === undefined) return false;
    this.entries.delete(key); this.entries.set(key, bytes); return true;
  }
  admit(key, bytes) {
    if (bytes > this.capacity) return false;
    if (this.touch(key)) return true;
    while (this.bytes + bytes > this.capacity) {
      const oldest = this.entries.keys().next().value;
      this.bytes -= this.entries.get(oldest); this.entries.delete(oldest); this.evictions++;
    }
    this.entries.set(key, bytes); this.bytes += bytes; return true;
  }
  clear() { this.entries.clear(); this.bytes = 0; }
}
function emptyRam(state) {
  return {directory: null, centroids: [], sketchRows: 0, tail: new Map(), hot: new LRU(state.ramCapacity)};
}
function rebuildRam(state) {
  const ram = emptyRam(state);
  ram.directory = {baseRows: state.s3.dataset.count, sealed: new Map()};
  ram.routing = state.s3.dataset.centroids.map(() => []);
  for (const block of state.s3.blocks) ram.routing[block.cluster].push(block);
  for (const block of state.s3.blocks) for (const row of block.rows ?? []) ram.directory.sealed.set(row.id, {row, block: block.id});
  ram.centroids = state.dataset.centroids;
  ram.sketchRows = state.dataset.count + ram.directory.sealed.size;
  return ram;
}
function addBlocks(state, groups, isBase = false) {
  const added = [];
  let pack = null;
  for (const group of groups) {
    if (!pack || pack.blocks.length === PACK_BLOCKS) {
      pack = {id: `sgpack-${state.s3.packs.length + 1}`, blocks: []}; state.s3.packs.push(pack);
    }
    const block = {...group, id: state.s3.blocks.length, pack: pack.id,
      offset: pack.blocks.length * BLOCK_BYTES,
      bytes: Math.ceil(BLOCK_BYTES * group.count / ROWS_PER_BLOCK), base: isBase};
    state.s3.blocks.push(block); pack.blocks.push(block.id); added.push(block);
    if (state.ram?.routing) state.ram.routing[block.cluster].push(block);
  }
  return added;
}
export function createSimulation({count = 1_000_000, seed = SEED, ssdCapacity = 256 * MiB, ramCapacity = 4 * MiB} = {}) {
  const dataset = generateDataset(count, seed);
  const state = {dataset, ramCapacity, status: 'running', acknowledged: 0, sequence: 0,
    nextId: count + 1, ssd: new LRU(ssdCapacity), warmCursor: 0, warmReads: 0,
    s3: {dataset, packs: [], blocks: [], logs: new Map(), root: {generation: 1, sequence: 0},
      highestGeneration: 1, runs: Math.ceil(count / 65536), lease: 1, fences: []}, ram: null};
  const groups = [];
  for (const c of dataset.centroids) {
    const start = c.firstId, end = start + c.count;
    for (let id = start; id < end; id += ROWS_PER_BLOCK) groups.push({cluster: c.id, firstId: id, count: Math.min(ROWS_PER_BLOCK, end - id)});
  }
  addBlocks(state, groups, true);
  state.ram = rebuildRam(state);
  return state;
}
function running(state) { if (state.status !== 'running') throw new Error('Restart the process first'); }
export function* blockRows(state, block) {
  if (block.base) for (let i = 0; i < block.count; i++) yield basePoint(state.dataset, block.firstId + i);
  else yield* block.rows;
}
// Scan the recovered logical model, including every represented base ID. The
// returned records do not depend on an acknowledgement list retained by RAM.
export function* scanRows(state) {
  running(state);
  for (let id = 1; id <= state.ram.directory.baseRows; id++) yield basePoint(state.dataset, id);
  yield* [...state.ram.directory.sealed.values()].map(entry => entry.row);
  yield* state.ram.tail.values();
}
export function writeBatch(state, position = {x: .5, y: .5}) {
  running(state);
  const random = prng(state.dataset.seed ^ state.nextId), cluster = assignCluster(state.dataset, position);
  const radius = state.dataset.centroids[cluster].radius;
  const rows = Array.from({length: 100}, () => ({id: state.nextId++, cluster,
    x: Math.max(.015, Math.min(.985, position.x + (random() - .5) * radius)),
    y: Math.max(.015, Math.min(.985, position.y + (random() - .5) * radius))}));
  for (const row of rows) row.cluster = assignCluster(state.dataset, row);
  const sequence = ++state.sequence;
  // Conditional durable create, THEN visibility and acknowledgement.
  state.s3.logs.set(sequence, {key: `sglog-${sequence}`, rows});
  for (const row of rows) state.ram.tail.set(row.id, row);
  state.acknowledged += rows.length;
  return {rows, sequence, shouldSeal: state.s3.logs.size >= SEAL_LOGS};
}
export function seal(state) {
  running(state);
  if (!state.ram.tail.size) return null;
  const rows = [...state.ram.tail.values()].sort((a, b) => a.cluster - b.cluster || a.id - b.id);
  const groups = [];
  for (const c of state.dataset.centroids) {
    const clusterRows = rows.filter(row => row.cluster === c.id);
    for (let i = 0; i < clusterRows.length; i += ROWS_PER_BLOCK) {
      const chunk = clusterRows.slice(i, i + ROWS_PER_BLOCK);
      groups.push({cluster: c.id, rows: chunk, count: chunk.length});
    }
  }
  const blocks = addBlocks(state, groups);
  // Pack, sgindex, sgmanifest and sgcluster are staged before this switch.
  state.s3.runs++;
  state.s3.root = {generation: ++state.s3.highestGeneration, sequence: state.sequence};
  // Sealed sglogs are pruned only after the new root is durable. Fence objects
  // live separately and are retained permanently, as the engine requires.
  state.s3.logs.clear(); state.ram = rebuildRamWithHot(state); state.warmCursor = 0;
  return {rows: rows.length, blocks, generation: state.s3.root.generation};
}
function rebuildRamWithHot(state) { const hot = state.ram.hot; const ram = rebuildRam(state); ram.hot = hot; return ram; }
function sketchDistance(state, block, query) {
  // Illustrative shared affine 5-bit codebook over this 2D projection. Sizes
  // below use 128D; this is not an ANN recall or engine-training benchmark.
  let best = Infinity;
  for (const row of blockRows(state, block)) {
    const x = Math.round(row.x * 31) / 31, y = Math.round(row.y * 31) / 31;
    best = Math.min(best, (query.x - x) ** 2 + (query.y - y) ** 2);
  }
  return best;
}
export function planQuery(state, point) {
  running(state);
  if (!Number.isFinite(point.x) || !Number.isFinite(point.y)) throw new Error('Query coordinates must be finite');
  // M31's 32 probes, scaled to 4 on the 25-center demonstration.
  const probes = Math.min(32, Math.max(4, Math.ceil(state.dataset.centroids.length / 8)));
  const clusters = state.ram.centroids.map(c => ({id: c.id, score: distance(c, point)}))
    .sort((a, b) => a.score - b.score || a.id - b.id).slice(0, probes).map(c => c.id);
  const candidates = clusters.flatMap(c => state.ram.routing[c]).map(block => ({block, score: sketchDistance(state, block, point)}))
    .sort((a, b) => a.score - b.score || a.block.id - b.block.id).slice(0, BUDGET.candidates).map(c => c.block);
  // The cold prefix is stable across cache changes. Beyond it, candidates are
  // read only if already local: repeating a query cannot fetch a new suffix.
  let coldBytes = 0, coldRequests = 0;
  const reads = [];
  for (const block of candidates) {
    const coldEligible = coldRequests < BUDGET.requests && coldBytes + block.bytes <= BUDGET.bytes;
    if (coldEligible) { coldBytes += block.bytes; coldRequests++; }
    const source = state.ram.hot.has(block.id) ? 'ram' : state.ssd.has(block.id) ? 'ssd' : 's3';
    if (coldEligible || source !== 's3') reads.push({block, source});
  }
  const sources = {ram: 0, ssd: 0, s3: 0};
  for (const read of reads) sources[read.source]++;
  const bytes = reads.filter(r => r.source === 's3').reduce((n, r) => n + r.block.bytes, 0);
  // The illustrative 1ms CPU budget is split across routing, selection and
  // reranking. Fetch sums local access and batches of four parallel ranges.
  const phases = [
    {name: 'route', tier: 'ram', ms: .25},
    {name: 'select', tier: 'ram', ms: .25},
    {name: 'fetch', tier: null, sources: {...sources}, ms: +(sources.ram * .1 + sources.ssd * .5 + Math.ceil(sources.s3 / 4) * 20).toFixed(1)},
    {name: 'rerank', tier: 'ram', ms: .5},
  ];
  const latency = +phases.reduce((sum, phase) => sum + phase.ms, 0).toFixed(1);
  return {point: {...point}, clusters, candidates, reads, sources, bytes, latency, phases};
}
export function fetchBlock(state, read, promoteToRam = true) {
  running(state);
  if (read.source === 'ram') state.ram.hot.touch(read.block.id);
  else {
    if (read.source === 'ssd') state.ssd.touch(read.block.id);
    else state.ssd.admit(read.block.id, read.block.bytes);
    if (promoteToRam) state.ram.hot.admit(read.block.id, read.block.bytes);
  }
}
export function rerank(state, plan) {
  running(state);
  const rows = plan.reads.flatMap(read => [...blockRows(state, read.block)]);
  rows.push(...state.ram.tail.values());
  return rows.map(row => ({...row, distance: distance(row, plan.point)}))
    .sort((a, b) => a.distance - b.distance || a.id - b.id).slice(0, 10);
}
export function query(state, point) {
  const plan = planQuery(state, point);
  for (const read of plan.reads) fetchBlock(state, read);
  return {...plan, results: rerank(state, plan)};
}
export function warmStep(state) {
  running(state);
  // Lowest-priority idle work, at most 256KiB, SSD only. When the namespace
  // exceeds capacity, fill free space and stop; never churn query LRU contents.
  const added = []; let bytes = 0;
  while (state.warmCursor < state.s3.blocks.length) {
    const block = state.s3.blocks[state.warmCursor];
    if (state.ssd.has(block.id)) { state.warmCursor++; continue; }
    if (bytes + block.bytes > 256 * 1024) break;
    if (state.ssd.bytes + block.bytes > state.ssd.capacity) break;
    state.warmCursor++; state.ssd.admit(block.id, block.bytes); added.push(block); bytes += block.bytes;
  }
  if (added.length) state.warmReads++;
  return added;
}
export function crash(state, loseDisk = false) {
  running(state); state.status = 'crashed'; state.ram = null;
  if (loseDisk) state.ssd.clear();
}
export const RESTART_PHASES = Object.freeze([
  'Wait out the old lease (10 seconds on the real server), then acquire a new lease.',
  'Publish the sglog takeover record and sgroot fence to stop the previous writer.',
  'Read the selected root, immutable manifests and run indexes from S3.',
  'Rebuild the ID directory, centroids and five-bit routing sketches.',
  'Replay every newer log batch into the unsealed RAM tail.',
]);
export function beginRestart(state) {
  if (state.status !== 'crashed') throw new Error('Crash the process first');
  state.status = 'recovering'; state.restartPhase = 0; state.ram = emptyRam(state);
}
export function restartStep(state) {
  if (state.status !== 'recovering') throw new Error('No restart in progress');
  const phase = state.restartPhase++;
  if (phase === 0) state.s3.lease++;
  if (phase === 1) state.s3.fences.push({log: ++state.sequence, root: ++state.s3.highestGeneration});
  if (phase === 3) state.ram = rebuildRam(state);
  if (phase === 4) {
    for (const [sequence, log] of state.s3.logs) {
      if (sequence > state.s3.root.sequence) for (const row of log.rows) state.ram.tail.set(row.id, row);
    }
    state.status = 'running'; state.warmCursor = 0;
  }
  return {phase, progress: state.restartPhase / RESTART_PHASES.length, caption: RESTART_PHASES[phase]};
}
export function restart(state) { beginRestart(state); while (state.status === 'recovering') restartStep(state); }
export function sizes(state) {
  const sealed = state.dataset.count + state.s3.blocks.filter(b => !b.base).reduce((n, b) => n + b.count, 0);
  const tailRows = [...state.s3.logs.values()].reduce((n, log) => n + log.rows.length, 0);
  const centroids = state.dataset.centroids.length * 128 * 4;
  const sketches = sealed * (128 * 5 / 8 + 4 + 8); // codes + ID offset + posting sequence
  const directory = (sealed + tailRows) * 24;
  const logs = tailRows * 640;
  const packs = state.s3.blocks.reduce((n, b) => n + b.bytes, 0) + sketches;
  const indexes = sealed * 24, manifests = state.s3.blocks.length * 68;
  const catalog = state.s3.blocks.length * 80;
  const roots = 4096 + state.s3.runs * 256;
  const fences = state.s3.fences.length * 256;
  const ram = state.ram ? {directory: state.ram.directory ? directory : 0,
    centroids: state.ram.centroids.length * 128 * 4, sketches: state.ram.sketchRows * 92,
    tail: state.ram.tail.size * 640, hot: state.ram.hot.bytes} : {directory: 0, centroids: 0, sketches: 0, tail: 0, hot: 0};
  return {sealed, tailRows, directory, centroids, sketches, logs, packs, indexes, manifests, catalog, roots, fences,
    s3: packs + logs + indexes + manifests + catalog + centroids + roots + fences + 256,
    ram, ramTotal: Object.values(ram).reduce((a, b) => a + b, 0)};
}
